-- Hyprland entry point. Each module has a single job; edit them freely.
-- shell.lua and theme.lua are generated by `tfem generate` from config.json
-- and theme.toml: change those files instead of the generated ones.

require("shell")               -- generated: name of the Quickshell config
require("config/variables")    -- modifier key, apps, keyboard layout
require("config/monitors")     -- screens
require("config/settings")     -- behaviour: input, gestures, misc
require("config/animations")   -- curves and animations
require("config/autostart")    -- programs started with Hyprland
require("config/keybinds")     -- every shortcut, with a description

-- The theme comes last so its colors, gaps and blur win.
-- >>> generated: hyprland >>>
require("theme")
-- <<< generated: hyprland <<<
